def basis(w):
    cols=[np.ones_like(x),v,v*v,1/v,1/v**2,np.exp(-v),np.sin(v),x,x*x,x**3,np.sqrt(x),np.sin(x),x*v,
          np.cos(w*t),np.sin(w*t),v*np.cos(w*t),v*np.sin(w*t),x*np.cos(w*t),x*np.sin(w*t)]
    return np.column_stack(cols)
best=None
for w in np.linspace(0.1,6,1192):
    A=basis(w)
    c,_,_,_=np.linalg.lstsq(A,dv_dt,rcond=None)
    r=1-np.sum((dv_dt-A@c)**2)/np.sum((dv_dt-dv_dt.mean())**2)
    if best is None or r>best[0]: best=(r,w,c)
print(best[0],best[1]); print(np.round(best[2],4))

